def score(item, bins):
    residual = item - bins
    return np.array(residual, dtype=np.int64)

def score(item, bins):
    resid = bins - item
    sc = np.where(resid == 0, 1000000000.0, 1000000.0 - resid)
    return np.where(resid <= 0, 2000000000.0, sc)

def score(item, bins):
    r = bins - item
    d = r - 40.0
    s = -1.0 * (d * d) - 0.001 * r
    return np.asarray(s, dtype=np.float64)
